## Final Result:

::: {.panel-sidebar .py-3 .px-3 .mb-4 fig-align="center" .border .bg-light .shadow-sm}

#### Filters:
```{ojs}

viewof bill_length_min = Inputs.range(
  [32, 50], 
  {value: 35, step: 1, label: "Bill length (min):"}
)
viewof islands = Inputs.checkbox(
  ["Torgersen", "Biscoe", "Dream"], 
  { value: ["Torgersen", "Biscoe"], 
    label: "Islands:"
  }
)
```
:::


::: {.panel-fill .py-3 .px-3 .mb-4 fig-align="center" .border .bg-light .shadow-sm}

::: {.panel-tabset}

## Plot
```{ojs}

//| echo: false
filtered = pdata.filter(function(penguin) {
  return bill_length_min < penguin.bill_length_mm &&
         islands.includes(penguin.island);
})

Plot.rectY(filtered, 
  Plot.binX(
    {y: "count"}, 
    {x: "body_mass_g", fill: "species", thresholds: 20}
  ))
  .plot({
    facet: {
      data: filtered,
      x: "sex",
      y: "species",
      marginRight: 80
    },
    marks: [
      Plot.frame(),
    ]
  }
)
```

